begin;
select no_plan();
insert into auth.users(id,aud,role,email,email_confirmed_at) values('61000000-0000-4000-8000-000000000001','authenticated','authenticated','private@example.test',now());
set local role authenticated;
select set_config('request.jwt.claim.sub','61000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.save_my_directory_profile('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1')$$,'old callers remain compatible');
select is(public.list_public_member_profiles()->'items'->0->>'public_email',null::text,'existing consent never publishes email');
select lives_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'sign_in',null,null,false)$$,'contact values may be saved privately');
select is(public.list_public_member_profiles()->'items'->0->>'public_email',null::text,'no consent means no publication');
select lives_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'sign_in',null,'https://linkedin.com/in/builder',true)$$,'confirmed email sharing works');
select throws_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'sign_in','spoof@example.test',null,true)$$,'22023','Your sign-in email changed. Select it again and confirm sharing.','browser cannot choose another sign-in email');
select is(public.list_public_member_profiles()->'items'->0->>'public_email','private@example.test','sign-in email resolved server-side without browser address');
select throws_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'custom','x@example.test','https://linkedin.com.evil.test/in/x',true)$$,'22023','Enter an HTTPS LinkedIn profile URL','reject lookalike host');
select throws_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'custom',E'x@example.test\nBcc:x@y.test',null,true)$$,'22023','Enter a valid public email','reject header injection');
reset role;
update auth.users set email='changed@example.test' where id='61000000-0000-4000-8000-000000000001';
select is(public.list_public_member_profiles()->'items'->0->>'public_email',null::text,'changed sign-in address requires new choice');
set local role authenticated;
select is(public.get_my_directory_profile()->>'contact_consent','false','email change resets editor consent');
select lives_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'custom','contact@example.test',null,true)$$,'separate email supported');
select is(public.list_public_member_profiles()->'items'->0->>'public_email','contact@example.test','only chosen separate email public');
select lives_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'custom','contact@example.test','https://linkedin.com/in/builder',false)$$,'unchecking sharing retains private choices');
select is(public.list_public_member_profiles()->'items'->0->>'public_email',null::text,'unchecked consent hides email');
select is(public.list_public_member_profiles()->'items'->0->>'linkedin_url',null::text,'unchecked consent hides LinkedIn');
select lives_ok($$select public.save_my_directory_profile_with_contacts('Contact Builder','',array[]::text[],true,false,'2026-10-20-public-directory-v1',null,'none',null,null,false)$$,'contact withdrawal supported');
select is(public.list_public_member_profiles()->'items'->0->>'public_email',null::text,'withdrawn email absent');
select lives_ok($$select public.hide_my_directory_profile()$$,'profile hiding supported');
select is(public.list_public_member_profiles()->>'total','0','hidden contacts unavailable');
set local role anon;
select throws_ok($$select public.save_my_directory_profile_with_contacts('x','',array[]::text[],true,false,null,null,'none',null,null,false)$$,'42501',null,'anonymous cannot update contacts');
select * from finish();
rollback;
